using System.Data;
using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using WudilFood.Data;
using WudilFood.Models;
using WudilFood.ViewModels;
using WudilFood.Services;
namespace WudilFood.Controllers;
public class OrdersController(AppDb db,UserManager<AppUser> users):Controller{
 string? Uid=>User.FindFirstValue(ClaimTypes.NameIdentifier);
 List<int> GuestOrders()=>JsonSerializer.Deserialize<List<int>>(HttpContext.Session.GetString("guest-orders")??"[]")??new();
 bool CanManage(FoodOrder order)=>User.IsInRole(Roles.Admin)||order.CustomerId==Uid||order.Vendor.UserId==Uid||GuestOrders().Contains(order.Id);
 async Task<(List<CartEntry> Cart,PlatformSetting Settings)> LoadCheckoutViewData()
 {
  var cart=CartController.Get(HttpContext.Session);
  var ids=cart.Select(x=>x.ItemId).ToList();
  var settings=await db.Settings.AsNoTracking().FirstAsync();
  ViewBag.Settings=settings;
  ViewBag.Cart=cart;
  ViewBag.CartItems=ids.Count==0
   ? new List<MenuItem>()
   : await db.MenuItems.AsNoTracking().Include(x=>x.Vendor).Where(x=>ids.Contains(x.Id)).ToListAsync();
  return (cart,settings);
 }
 public async Task<IActionResult> Checkout(){if(User.Identity?.IsAuthenticated==true&&!User.IsInRole(Roles.Customer))return Forbid();var (cart,_)=await LoadCheckoutViewData();if(cart.Count==0)return RedirectToAction("Index","Cart");var address=Uid==null?null:(await db.Users.FindAsync(Uid))?.Address;return View(new CheckoutForm{LocalSlot=DateTime.Now.AddHours(1),DeliveryAddress=address});}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Checkout(CheckoutForm f){if(User.Identity?.IsAuthenticated==true&&!User.IsInRole(Roles.Customer))return Forbid();var (cart,settings)=await LoadCheckoutViewData();if(cart.Count==0)return RedirectToAction("Index","Cart");if(Uid==null&&(string.IsNullOrWhiteSpace(f.GuestName)||string.IsNullOrWhiteSpace(f.GuestEmail)||string.IsNullOrWhiteSpace(f.GuestPhone)))ModelState.AddModelError("","Name, email and phone are required for guest checkout.");if(f.Fulfillment==Fulfillment.Delivery&&(!settings.DeliveryEnabled||string.IsNullOrWhiteSpace(f.DeliveryAddress)))ModelState.AddModelError(nameof(f.DeliveryAddress),"Delivery is unavailable or an address is missing.");if(f.LocalSlot<DateTime.Now.AddMinutes(5)||f.LocalSlot>DateTime.Now.AddDays(30))ModelState.AddModelError(nameof(f.LocalSlot),"Select a time from 5 minutes to 30 days ahead.");if(!Enum.IsDefined(f.Fulfillment)||!Enum.IsDefined(f.PaymentMethod))ModelState.AddModelError("","Invalid checkout selection.");if(!ModelState.IsValid)return View(f);
 await using var tx=await db.Database.BeginTransactionAsync(IsolationLevel.Serializable);try{var ids=cart.Select(x=>x.ItemId).ToList();var items=await db.MenuItems.Include(x=>x.Schedules).Include(x=>x.Vendor).Where(x=>ids.Contains(x.Id)).ToListAsync();if(items.Count!=cart.Count||items.Select(x=>x.VendorId).Distinct().Count()!=1||items.Any(x=>x.Vendor.Status!=ApprovalStatus.Approved||!x.IsVisible||x.Mode==AvailabilityMode.Unavailable))throw new InvalidOperationException("Some items are no longer available.");var slotUtc=f.LocalSlot.ToUniversalTime();if(await db.VendorClosures.AnyAsync(x=>x.VendorId==items[0].VendorId&&x.StartsUtc<=slotUtc&&x.EndsUtc>=slotUtc))throw new InvalidOperationException("This vendor is closed during the selected time.");foreach(var entry in cart){var item=items.Single(x=>x.Id==entry.ItemId);if(entry.Quantity<1||entry.Quantity>item.Stock)throw new InvalidOperationException($"Insufficient quantity for {item.Name}.");var slot=TimeOnly.FromDateTime(f.LocalSlot);if(item.Mode==AvailabilityMode.Preorder&&!item.Schedules.Any(s=>s.Day==f.LocalSlot.DayOfWeek&&slot>=s.StartsAt&&slot<=s.EndsAt&&(f.LocalSlot.Date>DateTime.Now.Date||TimeOnly.FromDateTime(DateTime.Now)<s.OrderDeadline)&&(!s.Capacity.HasValue||s.Capacity.Value>=entry.Quantity)))throw new InvalidOperationException($"{item.Name} is not available for that slot or its deadline has passed.");if(item.Mode==AvailabilityMode.Immediate&&f.LocalSlot>DateTime.Now.AddHours(4))throw new InvalidOperationException($"{item.Name} is for immediate orders only.");item.Stock-=entry.Quantity;}
 var customerId=Uid;var isGuest=customerId==null;if(isGuest){var guest=new AppUser{UserName=$"guest-{Guid.NewGuid():N}@guest.local",Email=f.GuestEmail!.Trim(),FullName=f.GuestName!.Trim(),PhoneNumber=f.GuestPhone!.Trim(),Address=f.DeliveryAddress,EmailConfirmed=false};var created=await users.CreateAsync(guest);if(!created.Succeeded)throw new InvalidOperationException(string.Join("; ",created.Errors.Select(x=>x.Description)));var roleAdded=await users.AddToRoleAsync(guest,Roles.Customer);if(!roleAdded.Succeeded)throw new InvalidOperationException(string.Join("; ",roleAdded.Errors.Select(x=>x.Description)));customerId=guest.Id;}
 var order=new FoodOrder{Reference="WF-"+Guid.NewGuid().ToString("N")[..12].ToUpperInvariant(),CustomerId=customerId!,VendorId=items[0].VendorId,SlotUtc=f.LocalSlot.ToUniversalTime(),Fulfillment=f.Fulfillment,PaymentMethod=f.PaymentMethod,PaymentState=f.PaymentMethod==PaymentMethod.BankTransfer?PaymentState.PendingVerification:PaymentState.Unpaid,DeliveryAddress=f.DeliveryAddress?.Trim(),Note=f.Note,ItemsTotal=cart.Sum(x=>items.Single(i=>i.Id==x.ItemId).Price*x.Quantity),DeliveryFee=f.Fulfillment==Fulfillment.Delivery?settings.DeliveryFee:0,Lines=cart.Select(x=>{var item=items.Single(i=>i.Id==x.ItemId);return new OrderLine{MenuItemId=item.Id,ItemName=item.Name,UnitPrice=item.Price,Quantity=x.Quantity};}).ToList()};db.Orders.Add(order);db.Notices.Add(new Notice{UserId=items[0].Vendor.UserId,Text=$"New order {order.Reference} is awaiting review."});await db.SaveChangesAsync();await tx.CommitAsync();if(isGuest){var guestOrders=GuestOrders();guestOrders.Add(order.Id);HttpContext.Session.SetString("guest-orders",JsonSerializer.Serialize(guestOrders));}CartController.Put(HttpContext.Session,new());return RedirectToAction(nameof(Details),new{id=order.Id});}catch(Exception ex)when(ex is InvalidOperationException or DbUpdateException){await tx.RollbackAsync();ModelState.AddModelError("",ex is DbUpdateException?"Stock changed. Please retry checkout.":ex.Message);return View(f);}}
 [Authorize]public async Task<IActionResult> Index(){var q=db.Orders.AsNoTracking().Include(x=>x.Vendor).Include(x=>x.Customer).AsQueryable();if(User.IsInRole(Roles.Admin)){}else if(User.IsInRole(Roles.Vendor))q=q.Where(x=>x.Vendor.UserId==Uid);else q=q.Where(x=>x.CustomerId==Uid);return View(await q.OrderByDescending(x=>x.CreatedUtc).Take(100).ToListAsync());}
 public async Task<IActionResult> Details(int id){var o=await db.Orders.AsNoTracking().Include(x=>x.Lines).Include(x=>x.Vendor).Include(x=>x.Customer).Include(x=>x.Review).Include(x=>x.Rider).FirstOrDefaultAsync(x=>x.Id==id);if(o==null)return NotFound();if(!CanManage(o))return Forbid();ViewBag.CustomerCanManage=o.CustomerId==Uid||GuestOrders().Contains(o.Id);ViewBag.History=await db.OrderStatusHistories.AsNoTracking().Where(x=>x.FoodOrderId==id).OrderBy(x=>x.ChangedUtc).ToListAsync();if(User.IsInRole(Roles.Vendor)&&o.Fulfillment==Fulfillment.Delivery)ViewBag.Riders=await db.Riders.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.Name).ToListAsync();return View(o);}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Confirm(int id){var o=await db.Orders.Include(x=>x.Vendor).FirstOrDefaultAsync(x=>x.Id==id);if(o==null||!CanManage(o)||(o.CustomerId!=Uid&&!GuestOrders().Contains(id)))return NotFound();if(o.State!=OrderState.Delivered&&(o.State!=OrderState.Ready||o.Fulfillment==Fulfillment.Delivery))return BadRequest();o.State=OrderState.Completed;if(Uid!=null)db.Notices.Add(new Notice{UserId=Uid,Text=$"Order {o.Reference} is complete. You can now leave a review."});await db.SaveChangesAsync();return RedirectToAction(nameof(Details),new{id});}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Review(int id,int rating,string comment){var o=await db.Orders.Include(x=>x.Review).Include(x=>x.Vendor).FirstOrDefaultAsync(x=>x.Id==id);if(o==null||!CanManage(o)||(o.CustomerId!=Uid&&!GuestOrders().Contains(id)))return NotFound();if(o.State!=OrderState.Completed||o.Review!=null||rating<1||rating>5||string.IsNullOrWhiteSpace(comment)||comment.Length>1000)return BadRequest();db.Reviews.Add(new Review{FoodOrderId=id,Rating=rating,Comment=comment.Trim()});await db.SaveChangesAsync();return RedirectToAction(nameof(Details),new{id});}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Complain(int id,string text){var o=await db.Orders.Include(x=>x.Vendor).FirstOrDefaultAsync(x=>x.Id==id);if(o==null||!CanManage(o)||(o.CustomerId!=Uid&&!GuestOrders().Contains(id))||string.IsNullOrWhiteSpace(text)||text.Length>1500)return BadRequest();db.Complaints.Add(new Complaint{FoodOrderId=id,UserId=o.CustomerId,Text=text.Trim()});await db.SaveChangesAsync();return RedirectToAction(nameof(Details),new{id});}
 [HttpGet]public IActionResult Track()=>View();
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Track(string reference,string phone){if(string.IsNullOrWhiteSpace(reference)||string.IsNullOrWhiteSpace(phone))return View();var normalizedPhone=new string(phone.Where(char.IsDigit).ToArray());var order=await db.Orders.Include(x=>x.Customer).FirstOrDefaultAsync(x=>x.Reference==reference.Trim().ToUpper());var orderPhone=new string((order?.Customer.PhoneNumber??"").Where(char.IsDigit).ToArray());if(order==null||normalizedPhone.Length<7||orderPhone!=normalizedPhone){ModelState.AddModelError("","Order reference and phone number do not match.");return View();}var ids=GuestOrders();if(!ids.Contains(order.Id)){ids.Add(order.Id);HttpContext.Session.SetString("guest-orders",JsonSerializer.Serialize(ids));}return RedirectToAction(nameof(Details),new{id=order.Id});}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Reorder(int id){var order=await db.Orders.Include(x=>x.Vendor).Include(x=>x.Lines).ThenInclude(x=>x.MenuItem).FirstOrDefaultAsync(x=>x.Id==id);if(order==null||!CanManage(order)||(order.CustomerId!=Uid&&!GuestOrders().Contains(id)))return NotFound();if(order.State!=OrderState.Completed)return BadRequest("Only completed orders can be reordered.");var cart=new List<CartEntry>();foreach(var line in order.Lines){if(!line.MenuItem.IsVisible||line.MenuItem.Mode==AvailabilityMode.Unavailable||line.MenuItem.Stock<=0)continue;cart.Add(new CartEntry{ItemId=line.MenuItemId,Quantity=Math.Min(line.Quantity,line.MenuItem.Stock)});}if(cart.Count==0)return BadRequest("None of the items in this order are currently available.");CartController.Put(HttpContext.Session,cart);return RedirectToAction("Index","Cart");}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> RequestCancellation(int id,string reason,string? details){var order=await db.Orders.Include(x=>x.Vendor).FirstOrDefaultAsync(x=>x.Id==id);if(order==null||!CanManage(order)||(order.CustomerId!=Uid&&!GuestOrders().Contains(id)))return NotFound();if(!OrderWorkflow.CanCancel(order.State)||string.IsNullOrWhiteSpace(reason)||reason.Length>80||details?.Length>600)return BadRequest();var message=$"Cancellation request - {reason.Trim()}"+(string.IsNullOrWhiteSpace(details)?"":$": {details.Trim()}");db.Complaints.Add(new Complaint{FoodOrderId=id,UserId=order.CustomerId,Text=message});db.Notices.Add(new Notice{UserId=order.Vendor.UserId,Text=$"Cancellation requested for {order.Reference}: {reason.Trim()}."});await db.SaveChangesAsync();TempData["Message"]="Your cancellation request was sent to the vendor.";return RedirectToAction(nameof(Details),new{id});}
 [Authorize]public async Task<IActionResult> Notices()=>View(await db.Notices.Where(x=>x.UserId==Uid).OrderByDescending(x=>x.CreatedUtc).Take(100).ToListAsync());
}

